import json
out=[]
n=0
turn=0
for line in open('transcript.jsonl',encoding='utf-8'):
    try: rec=json.loads(line)
    except: continue
    turn+=1
    msg=rec.get('message') or {}
    content=msg.get('content')
    if not isinstance(content,list): continue
    for c in content:
        if isinstance(c,dict) and c.get('type')=='tool_use':
            n+=1
            name=c.get('name')
            inp=c.get('input',{})
            if name=='Bash': s=inp.get('command','')
            elif name in ('Read','NotebookRead'): s=inp.get('file_path','')
            elif name=='Grep': s="pattern=%r path=%r glob=%r"%(inp.get('pattern'),inp.get('path'),inp.get('glob'))
            elif name=='Glob': s="pattern=%r path=%r"%(inp.get('pattern'),inp.get('path'))
            elif name in ('Write','Edit'): s=inp.get('file_path','')
            else: s=json.dumps(inp)[:600]
            out.append("[turn %d] [call %d] %s: %s"%(turn,n,name,s))
open('transcript_tool_inputs.txt','w',encoding='utf-8').write('\n'.join(out)+'\n')
print("tool calls:",n,"records:",turn)
EOF
